// Minimal mixed-mode test (docs/tcs/object-model.md M-4): builds the same source for both the VM and tcs2c (lib), and functions in the C generated by tcs2c
// read and write objects created by the VM. Checks that the shape of the class payload ({ type_id; field... }) is the same in both.
public class Pt
{
    public int X;
    public float Y;
    public bool On;
    public Pt Next;
    public int Z;
}

public static class Game
{
    static Pt keep;

    public static void Setup()
    {
        keep = new Pt { X = 7, Y = 2.5f, On = true, Z = -3 };
        keep.Next = keep;
    }

    public static Pt Get() => keep;
    public static int Sum(Pt p) => p.X + p.Z;
    public static void Bump(Pt p) { p.X += 10; p.Y *= 2; }
    public static float Y(Pt p) => p.Y;
    public static void Frame() { }
    public static void Report() { }
}
